#pragma once
#include "shortcut_model.h"
#include <winrt/Windows.Data.Json.h>
#include <winrt/Windows.Foundation.Collections.h>
#include <roapi.h>
#include <stdexcept>
namespace moon::shortcuts {
struct JsonApartment {HRESULT result=RoInitialize(RO_INIT_MULTITHREADED);JsonApartment(){if(FAILED(result)&&result!=RPC_E_CHANGED_MODE)throw std::runtime_error("Cannot initialize shortcut JSON");}~JsonApartment(){if(result==S_OK)winrt::clear_factory_cache();if(SUCCEEDED(result))RoUninitialize();}};
inline std::string encode(const Bindings& values){JsonApartment apartment;using namespace winrt::Windows::Data::Json;JsonObject root,overrides;const auto initial=defaults();for(const auto& d:catalog()){const auto list=normalizeAll(forId(values,d.id));if(list==forId(initial,d.id))continue;JsonArray array;for(const auto& key:list)array.Append(JsonValue::CreateStringValue(winrt::to_hstring(key)));overrides.Insert(winrt::to_hstring(d.id),array);}root.Insert(L"format",JsonValue::CreateStringValue(L"moonsprite-shortcuts"));root.Insert(L"version",JsonValue::CreateNumberValue(2));root.Insert(L"bindings",overrides);return winrt::to_string(root.Stringify());}
inline Bindings decode(const std::string& text){if(text.size()>1024*1024)throw std::runtime_error("Shortcut JSON exceeds 1 MiB");JsonApartment apartment;using namespace winrt::Windows::Data::Json;JsonObject root;if(!JsonObject::TryParse(winrt::to_hstring(text),root))throw std::runtime_error("Invalid shortcut JSON");JsonObject source=root;if(root.HasKey(L"format")){if(root.GetNamedString(L"format",L"")!=L"moonsprite-shortcuts"||root.GetNamedNumber(L"version",0)!=2)throw std::runtime_error("Unsupported shortcut JSON version");source=root.GetNamedObject(L"bindings");}Bindings out=defaults();std::set<std::string> explicitIds;for(const auto& item:source){auto id=winrt::to_string(item.Key());if(find(id))explicitIds.insert(id);}for(const auto& item:source){auto id=winrt::to_string(item.Key());if(!find(id)){const std::map<std::string,std::string> aliases{{"temporaryMove","tool.move.quick"},{"temporaryEyedropper","tool.eyedropper.quick"},{"temporaryPan","tool.hand.quick"}};auto alias=aliases.find(id);if(alias==aliases.end()||explicitIds.count(alias->second))continue;id=alias->second;}std::vector<std::string> keys;const auto value=item.Value();if(value.ValueType()==JsonValueType::String)keys.push_back(winrt::to_string(value.GetString()));else if(value.ValueType()==JsonValueType::Array){for(const auto& v:value.GetArray()){if(v.ValueType()!=JsonValueType::String)throw std::runtime_error("Shortcut binding must contain strings");keys.push_back(winrt::to_string(v.GetString()));}}else continue;if(keys.size()>64)throw std::runtime_error("Too many bindings for one shortcut");out[id].clear();for(const auto& key:keys){if(key.size()>256||!supportedBinding(id,key))throw std::runtime_error("Unsupported shortcut binding");assign(out,id,key);}}return out;}
}
